import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"创游世界脚本实战架构入门","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界脚本实战架构入门.md","filePath":"脚本系统/专题研究/创游世界脚本实战架构入门.md","lastUpdated":1776864657000}'),h={name:"脚本系统/专题研究/创游世界脚本实战架构入门.md"};function d(n,l,p,o,t,c){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游世界脚本实战架构入门" tabindex="-1">创游世界脚本实战架构入门 <a class="header-anchor" href="#创游世界脚本实战架构入门" aria-label="Permalink to “创游世界脚本实战架构入门”">​</a></h1><p>本专题不是单纯罗列积木，而是把当前知识库里已经整理出的组件、作用域、广播、UI、系统脚本等内容，收束成一套更接近“实际做项目”的脚本架构思路。</p><p>它要解决的核心问题是：<strong>在创游世界里，功能不是怎么拼出来，而是怎么不拼乱。</strong></p><h2 id="_1-实战里最常见的混乱来源" tabindex="-1">1. 实战里最常见的混乱来源 <a class="header-anchor" href="#_1-实战里最常见的混乱来源" aria-label="Permalink to “1. 实战里最常见的混乱来源”">​</a></h2><p>很多工程越做越乱，通常不是因为不会写积木，而是因为下面这些问题：</p><ul><li>什么状态都往一个地方写</li><li>UI 直接操控地图逻辑</li><li>多个对象互相强依赖</li><li>一个组件既管数据又管表现又管流程</li><li>地图属性、系统属性、自身属性混着用</li><li>旧版本 UI 写法和新版本推荐写法混在一起</li></ul><p>所以脚本实战的重点不是“多会几个积木”，而是： <strong>会不会分层，会不会让数据流清晰。</strong></p><hr><h2 id="_2-建议的最小架构单位-对象-组件-状态-入口" tabindex="-1">2. 建议的最小架构单位：对象 + 组件 + 状态 + 入口 <a class="header-anchor" href="#_2-建议的最小架构单位-对象-组件-状态-入口" aria-label="Permalink to “2. 建议的最小架构单位：对象 + 组件 + 状态 + 入口”">​</a></h2><p>在创游世界里，一个可维护的功能单元通常至少包含：</p><ul><li>一个对象：功能真正挂载的载体</li><li>一个或多个组件：能力来源</li><li>一组状态：记录这个对象当前处于什么情况</li><li>一个或多个入口：什么时候执行、由谁调用、如何触发</li></ul><h3 id="例子-一扇可交互门" tabindex="-1">例子：一扇可交互门 <a class="header-anchor" href="#例子-一扇可交互门" aria-label="Permalink to “例子：一扇可交互门”">​</a></h3><p>可以拆成：</p><ul><li>对象：门</li><li>组件：可互动、物理/阻挡、自定义组件</li><li>状态：是否开启、是否锁定</li><li>入口：玩家交互时、收到广播时、执行自定义指令时</li></ul><p>如果这样拆，门就不只是“一个会开关的贴图”，而是一个可被多个系统调用的功能单元。</p><hr><h2 id="_3-先分清四层数据作用域" tabindex="-1">3. 先分清四层数据作用域 <a class="header-anchor" href="#_3-先分清四层数据作用域" aria-label="Permalink to “3. 先分清四层数据作用域”">​</a></h2><p>当前知识库可确认的核心作用域有：</p><ul><li>局部变量</li><li>自身属性</li><li>当前地图属性</li><li>系统属性</li></ul><h3 id="_3-1-局部变量" tabindex="-1">3.1 局部变量 <a class="header-anchor" href="#_3-1-局部变量" aria-label="Permalink to “3.1 局部变量”">​</a></h3><p>适合：</p><ul><li>当前一次执行过程中临时使用的数据</li><li>中间计算结果</li><li>不需要跨多次触发保留的值</li></ul><p>不适合：</p><ul><li>记录长期状态</li><li>给 UI 或其他对象长期读取</li></ul><h3 id="_3-2-自身属性" tabindex="-1">3.2 自身属性 <a class="header-anchor" href="#_3-2-自身属性" aria-label="Permalink to “3.2 自身属性”">​</a></h3><p>适合：</p><ul><li>某个对象自己的状态</li><li>例如门是否开启、怪物是否已激活、机关是否已触发</li></ul><p>这是最常用、也最安全的对象级状态层。</p><h3 id="_3-3-当前地图属性" tabindex="-1">3.3 当前地图属性 <a class="header-anchor" href="#_3-3-当前地图属性" aria-label="Permalink to “3.3 当前地图属性”">​</a></h3><p>适合：</p><ul><li>当前地图范围内共享的数据</li><li>例如关卡进度、地图内任务状态、当前波次、地图倒计时</li></ul><p>如果某个状态需要在地图中多个对象之间共享，但不必跨全局系统长期存在，优先考虑地图属性。</p><h3 id="_3-4-系统属性" tabindex="-1">3.4 系统属性 <a class="header-anchor" href="#_3-4-系统属性" aria-label="Permalink to “3.4 系统属性”">​</a></h3><p>适合：</p><ul><li>更高层级、跨地图或跨系统的全局状态</li><li>例如全局设置、联机房间状态、系统级开关</li></ul><p>系统属性不要滥用。否则后期你会发现一堆逻辑都在“抢写同一层全局状态”。</p><hr><h2 id="_4-建议的分层思路" tabindex="-1">4. 建议的分层思路 <a class="header-anchor" href="#_4-建议的分层思路" aria-label="Permalink to “4. 建议的分层思路”">​</a></h2><h3 id="第一层-对象内部逻辑" tabindex="-1">第一层：对象内部逻辑 <a class="header-anchor" href="#第一层-对象内部逻辑" aria-label="Permalink to “第一层：对象内部逻辑”">​</a></h3><p>处理对象自己的事情：</p><ul><li>受击</li><li>播动画</li><li>改朝向</li><li>改自身属性</li><li>生成子物体</li><li>销毁自身</li></ul><p>这层尽量不要直接操控全局流程。</p><h3 id="第二层-地图内协作逻辑" tabindex="-1">第二层：地图内协作逻辑 <a class="header-anchor" href="#第二层-地图内协作逻辑" aria-label="Permalink to “第二层：地图内协作逻辑”">​</a></h3><p>处理同一张地图中的对象协作：</p><ul><li>门和开关联动</li><li>怪物死亡后掉落奖励</li><li>一组机关共同开启</li><li>地图进度推进</li></ul><p>这层优先考虑地图属性和广播。</p><h3 id="第三层-ui-展示逻辑" tabindex="-1">第三层：UI 展示逻辑 <a class="header-anchor" href="#第三层-ui-展示逻辑" aria-label="Permalink to “第三层：UI 展示逻辑”">​</a></h3><p>处理：</p><ul><li>显示当前血量</li><li>显示货币数</li><li>提示任务状态</li><li>更新按钮文本和进度条</li></ul><p>UI 层尽量少直接写玩法逻辑，更适合做“显示”和“交互入口”。</p><h3 id="第四层-系统级流程逻辑" tabindex="-1">第四层：系统级流程逻辑 <a class="header-anchor" href="#第四层-系统级流程逻辑" aria-label="Permalink to “第四层：系统级流程逻辑”">​</a></h3><p>处理：</p><ul><li>胜负判定</li><li>切换地图</li><li>计时器</li><li>声音系统</li><li>联机状态</li></ul><p>这层是最上层，适合集中管理游戏流程，而不是承载具体某一个物体的小逻辑。</p><hr><h2 id="_5-广播为什么是架构关键" tabindex="-1">5. 广播为什么是架构关键 <a class="header-anchor" href="#_5-广播为什么是架构关键" aria-label="Permalink to “5. 广播为什么是架构关键”">​</a></h2><p>广播最重要的价值，不是“方便”，而是“解耦”。</p><h3 id="不推荐的写法思路" tabindex="-1">不推荐的写法思路 <a class="header-anchor" href="#不推荐的写法思路" aria-label="Permalink to “不推荐的写法思路”">​</a></h3><ul><li>某个按钮脚本里直接到处找对象改状态</li><li>某个怪物死亡时直接硬连 UI、奖励、任务系统</li><li>某个 UI 组件直接把地图里很多东西都写一遍</li></ul><p>这样做短期能跑，长期一定乱。</p><h3 id="推荐的思路" tabindex="-1">推荐的思路 <a class="header-anchor" href="#推荐的思路" aria-label="Permalink to “推荐的思路”">​</a></h3><p>让事件先发生，再让各系统自己响应：</p><ul><li>玩家死亡 → 发送广播</li><li>UI 收到广播后弹出失败界面</li><li>任务系统收到广播后记录失败次数</li><li>音效系统收到广播后播放音效</li></ul><p>这样每个系统只关心“我收到什么”，而不是“我要亲自操控全世界”。</p><hr><h2 id="_6-自定义组件最适合承担什么职责" tabindex="-1">6. 自定义组件最适合承担什么职责 <a class="header-anchor" href="#_6-自定义组件最适合承担什么职责" aria-label="Permalink to “6. 自定义组件最适合承担什么职责”">​</a></h2><p>自定义组件非常适合承担三种职责：</p><h3 id="_6-1-状态容器" tabindex="-1">6.1 状态容器 <a class="header-anchor" href="#_6-1-状态容器" aria-label="Permalink to “6.1 状态容器”">​</a></h3><p>例如：</p><ul><li>是否被激活</li><li>当前等级</li><li>冷却剩余</li><li>是否已领取奖励</li></ul><h3 id="_6-2-可复用行为模块" tabindex="-1">6.2 可复用行为模块 <a class="header-anchor" href="#_6-2-可复用行为模块" aria-label="Permalink to “6.2 可复用行为模块”">​</a></h3><p>例如：</p><ul><li>一个门组件</li><li>一个可采集资源点组件</li><li>一个签到奖励组件</li><li>一个抽奖机组件</li></ul><h3 id="_6-3-对外接口层" tabindex="-1">6.3 对外接口层 <a class="header-anchor" href="#_6-3-对外接口层" aria-label="Permalink to “6.3 对外接口层”">​</a></h3><p>通过“指令”对外提供统一调用方式。</p><p>这意味着别的对象没必要知道你内部怎么写，只需要知道：</p><ul><li>执行哪个指令</li><li>提供什么参数</li><li>会产生什么结果</li></ul><p>这就是可维护性的关键。</p><hr><h2 id="_7-ui-层最容易犯的错" tabindex="-1">7. UI 层最容易犯的错 <a class="header-anchor" href="#_7-ui-层最容易犯的错" aria-label="Permalink to “7. UI 层最容易犯的错”">​</a></h2><h3 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to “常见错误”">​</a></h3><ul><li>在 UI 里堆大量玩法主逻辑</li><li>UI 和地图对象互相硬连</li><li>一个按钮直接控制很多对象内部状态</li><li>不区分地图 UI、操作 UI、物体 UI 的职责</li></ul><h3 id="更推荐的思路" tabindex="-1">更推荐的思路 <a class="header-anchor" href="#更推荐的思路" aria-label="Permalink to “更推荐的思路”">​</a></h3><p>UI 做三件事就够了：</p><ol><li>展示状态</li><li>提供交互入口</li><li>通过广播或明确入口通知下层逻辑</li></ol><p>例如：</p><ul><li>点击按钮 → 发广播 / 调用某对象指令</li><li>地图状态变化 → UI 收到通知后刷新文本</li><li>玩家属性变化 → 物体 UI 或地图 UI 更新显示</li></ul><hr><h2 id="_8-适合新手练的-4-个架构闭环" tabindex="-1">8. 适合新手练的 4 个架构闭环 <a class="header-anchor" href="#_8-适合新手练的-4-个架构闭环" aria-label="Permalink to “8. 适合新手练的 4 个架构闭环”">​</a></h2><h3 id="_8-1-门机关闭环" tabindex="-1">8.1 门机关闭环 <a class="header-anchor" href="#_8-1-门机关闭环" aria-label="Permalink to “8.1 门机关闭环”">​</a></h3><p>包含：</p><ul><li>按钮</li><li>门</li><li>广播或指令</li><li>自身属性</li></ul><p>能学会：交互、状态、事件、对象协作。</p><h3 id="_8-2-血量显示闭环" tabindex="-1">8.2 血量显示闭环 <a class="header-anchor" href="#_8-2-血量显示闭环" aria-label="Permalink to “8.2 血量显示闭环”">​</a></h3><p>包含：</p><ul><li>生命组件</li><li>受伤逻辑</li><li>UI 血条</li><li>广播或状态同步</li></ul><p>能学会：玩法状态到界面显示的同步。</p><h3 id="_8-3-货币收集闭环" tabindex="-1">8.3 货币收集闭环 <a class="header-anchor" href="#_8-3-货币收集闭环" aria-label="Permalink to “8.3 货币收集闭环”">​</a></h3><p>包含：</p><ul><li>掉落物 / 可拾取物</li><li>玩家碰撞或交互</li><li>地图或系统级货币变量</li><li>UI 货币条</li></ul><p>能学会：拾取、累计、界面更新、数据归属。</p><h3 id="_8-4-奖励领取闭环" tabindex="-1">8.4 奖励领取闭环 <a class="header-anchor" href="#_8-4-奖励领取闭环" aria-label="Permalink to “8.4 奖励领取闭环”">​</a></h3><p>包含：</p><ul><li>按钮</li><li>条件判定</li><li>发奖逻辑</li><li>已领取状态记录</li><li>UI 文本变化</li></ul><p>能学会：条件、状态锁定、一次性奖励流程。</p><hr><h2 id="_9-一个更稳的实战原则" tabindex="-1">9. 一个更稳的实战原则 <a class="header-anchor" href="#_9-一个更稳的实战原则" aria-label="Permalink to “9. 一个更稳的实战原则”">​</a></h2><p>做功能时尽量按下面顺序思考：</p><ol><li>这个功能属于哪个对象？</li><li>需要哪些组件？</li><li>状态应该存在哪一层？</li><li>谁来触发它？</li><li>谁需要知道结果？</li><li>结果是直接调用，还是发广播？</li><li>UI 是主逻辑，还是只负责显示？</li></ol><p>如果这七个问题能先想清楚，脚本大概率就不会乱得太夸张。</p><hr><h2 id="_10-与现有知识库的关系" tabindex="-1">10. 与现有知识库的关系 <a class="header-anchor" href="#_10-与现有知识库的关系" aria-label="Permalink to “10. 与现有知识库的关系”">​</a></h2><p>这份文档相当于把以下文档进行“项目视角重组”：</p><ul><li><code>脚本界面与积木知识索引</code></li><li><code>自定义组件深度解析</code></li><li><code>脚本作用域与数据流深度研究</code></li><li><code>系统级脚本能力解析</code></li><li><code>广播机制深度解析</code></li><li><code>UI系统与切换机制解析</code></li><li><code>联机UI演进专题</code></li></ul><p>它不负责提供逐张证据，而是负责把这些知识变成一套更像“做项目的方法论”。</p><hr><h2 id="_11-可检索关键词" tabindex="-1">11. 可检索关键词 <a class="header-anchor" href="#_11-可检索关键词" aria-label="Permalink to “11. 可检索关键词”">​</a></h2><ul><li>创游世界脚本架构</li><li>创游世界项目结构</li><li>自定义组件怎么设计</li><li>地图属性和系统属性区别</li><li>广播怎么解耦</li><li>UI 逻辑怎么分层</li><li>创游世界实战思路</li><li>脚本功能怎么不写乱</li><li>对象状态存哪里</li><li>创游世界系统设计入门</li></ul>',118)])])}const b=i(h,[["render",d]]);export{_ as __pageData,b as default};
